import { Table, TranslatedFieldColumn, BooleanColumn, TableNameColumn, StringColumn, ReferenceColumn } from '../../db'

export const sys_ui_section = Table({
    name: 'sys_ui_section',
    extends: 'sys_metadata',
    schema: {
        caption: TranslatedFieldColumn({
            mandatory: false,
            label: 'Caption',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        header: BooleanColumn({ mandatory: false, label: 'Header', read_only: false, active: true, maxLength: 40 }),
        name: TableNameColumn({ mandatory: false, label: 'Table', read_only: false, active: true, maxLength: 80 }),
        roles: StringColumn({
            mandatory: false,
            label: 'Roles',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        sys_overrides: ReferenceColumn({
            mandatory: false,
            label: 'Overrides',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_section',
        }),
        sys_user: ReferenceColumn({
            mandatory: false,
            label: 'Sys user',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_user',
        }),
        title: BooleanColumn({ mandatory: false, label: 'Title', read_only: false, active: true, maxLength: 40 }),
        view: ReferenceColumn({
            mandatory: false,
            label: 'View',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_view',
        }),
        view_name: StringColumn({
            mandatory: false,
            label: 'View name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
    },
})
